begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
\ir free_registration_fixture.inc
select pg_temp.register(1);
select ok(not has_table_privilege('anon','public.free_registrations','select'),'anon has no registrant read');
select ok(not has_table_privilege('authenticated','public.free_registrations','select'),'owner base table is private');
select ok(not has_table_privilege('service_role','public.free_registrations','insert'),'service cannot bypass atomic RPC');
select ok(not has_table_privilege('authenticated','public.free_registration_requests','select'),'no request proof read');
select ok((select relrowsecurity from pg_class where oid='public.free_registrations'::regclass),'registrations RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.free_registration_requests'::regclass),'receipts RLS enabled');
select ok(not has_function_privilege('anon','public.server_confirm_free_registration(uuid,uuid,text,text,integer,text,jsonb)','execute'),'anonymous direct creation denied');
select ok(not has_function_privilege('authenticated','public.server_confirm_free_registration(uuid,uuid,text,text,integer,text,jsonb)','execute'),'owner direct creation denied');
select ok(not has_function_privilege('anon','public.server_resolve_free_registration(uuid,text)','execute'),'anonymous direct proof resolution denied');
select ok(not has_function_privilege('authenticated','public.server_lookup_free_ticket_collection(text)','execute'),'owner direct private collection denied');
select ok(not has_function_privilege('anon','public.server_consume_free_rsvp_rate_limit(text,text)','execute'),'rate RPC service only');
set local role authenticated;
select is(public.get_organizer_free_registration_metrics('b6200000-0000-4000-8000-000000000001')->>'registrationCount','1','owner registration count');
select is(public.get_organizer_free_registration_metrics('b6200000-0000-4000-8000-000000000001')->>'reservedAdmissions','2','owner reserved quantity');
select is(public.get_organizer_free_registration_metrics('b6200000-0000-4000-8000-000000000001')->>'remaining','1','owner remaining capacity');
select is(public.get_organizer_free_admissions('b6200000-0000-4000-8000-000000000001')->'admissions','[]'::jsonb,'blank lookup reveals no guest list');
select is(jsonb_array_length(public.get_organizer_free_admissions('b6200000-0000-4000-8000-000000000001','Pat')->'admissions'),2,'literal name search returns individual admissions');
select is(jsonb_array_length(public.get_organizer_free_admissions('b6200000-0000-4000-8000-000000000001','pat@example.invalid')->'admissions'),2,'exact email lookup');
select is(public.get_organizer_free_admissions('b6200000-0000-4000-8000-000000000001','@example')->'admissions','[]'::jsonb,'email substring is not a guest search');
select is(public.get_organizer_free_admissions('b6200000-0000-4000-8000-000000000001','%')->'admissions','[]'::jsonb,'percent is literal');
select ok(public.get_organizer_free_admissions('b6200000-0000-4000-8000-000000000001','Pat',1)->'nextCursor'<>'null'::jsonb,'bounded cursor returned');
select is(jsonb_array_length(public.get_organizer_free_admissions('b6200000-0000-4000-8000-000000000001','Pat',1,
 public.get_organizer_free_admissions('b6200000-0000-4000-8000-000000000001','Pat',1)->'nextCursor')->'admissions'),1,'second page returns remaining ticket');
select ok(public.get_organizer_free_admissions('b6200000-0000-4000-8000-000000000001','Pat')::text !~ 'credential|access_hash|request_id|stripe','owner projection contains no credential/proof/provider data');
select throws_ok($$select public.get_organizer_free_admissions('b6200000-0000-4000-8000-000000000001','Pat',51)$$,'22023','Invalid admission query','max 50 enforced');
select throws_ok($$select public.get_organizer_free_admissions('b6200000-0000-4000-8000-000000000001','Pat',1,'{}')$$,'22023','Invalid admission query','malformed cursor rejected');
reset role;
create temporary table free_manual_selector as select id from public.tickets where event_id='b6200000-0000-4000-8000-000000000001' order by id limit 1;
grant select on free_manual_selector to authenticated;
set local role authenticated;
select is(public.redeem_owned_ticket('b6200000-0000-4000-8000-000000000001',(select id from free_manual_selector))->>'outcome','admitted','owned manual admission uses same writer');
select is(public.get_organizer_free_registration_metrics('b6200000-0000-4000-8000-000000000001')->>'checkedIn','1','owner metrics see check-in');
select set_config('request.jwt.claim.sub','b6100000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.get_organizer_free_registration_metrics('b6200000-0000-4000-8000-000000000001')$$,'42501','Event unavailable','cross-owner metrics denied');
select throws_ok($$select public.get_organizer_free_admissions('b6200000-0000-4000-8000-000000000001','Pat')$$,'42501','Event unavailable','cross-owner guest lookup denied');
select throws_ok($$select public.redeem_owned_ticket('b6200000-0000-4000-8000-000000000001',(select id from free_manual_selector))$$,'42501','Event unavailable','cross-owner manual admission denied');
reset role;
select public.server_consume_free_rsvp_rate_limit(repeat('b',64),'create') from generate_series(1,10);
select is(public.server_consume_free_rsvp_rate_limit(repeat('b',64),'create')->>'allowed','false','create rate limit enforced');
select is(public.server_consume_free_rsvp_rate_limit(repeat('b',64),'status')->>'allowed','true','status has separate rate bucket');
select is(public.server_consume_free_rsvp_rate_limit(repeat('c',64),'create')->>'allowed','true','different identity separate bucket');
set constraints all immediate;
select * from finish();
rollback;
